SELECT id, product_name, category, brand, price, cost, stock_qty, launch_date, tags, supplier_id, NTILE(3) OVER (ORDER BY price DESC, id) AS price_bucket, LAST_VALUE(stock_qty, TRUE) OVER (PARTITION BY category ORDER BY stock_qty, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS last_known_stock_qty, MIN(cost) OVER (PARTITION BY supplier_id) AS supplier_id_min_cost, SUM(stock_qty) OVER (ORDER BY price, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS cumulative_stock_qty FROM products;
